    const commit = calls.find(c => c.label === 'commit')
    const probs = []
    if (after !== sc.after) probs.push('agents after the scatter: ' + after + ' (expected ' + sc.after + ')')
    if (!!result.landed !== sc.landed) probs.push('landed ' + result.landed)
    if (sc.routed && !(result.reviewRouted && result.reviewRouted.findings.length === sc.routed)) probs.push('reviewRouted ' + JSON.stringify(result.reviewRouted))
    if (commit && /1a\. The gate below ran/.test(commit.prompt) !== !!sc.step1a) probs.push('step 1a ' + !sc.step1a)
    if (commit && !/4\. Start the two microGPT programs/.test(commit.prompt)) probs.push('no microGPT step')
    if (commit && sc.held && !/5\. Keep every wip\/ worktree/.test(commit.prompt)) probs.push('held: no keep step')
    if (commit && !sc.held && !/git worktree remove --force/.test(commit.prompt)) probs.push('no --force removal')
    for (const c of calls) {
      if (/undefined|\[object Object\]|NaN/.test(c.prompt.replace(/reportText: undefined|recordText: undefined/g, ''))) probs.push(c.label + ' prompt holds undefined/[object Object]/NaN')
      if (c.label.startsWith('skeptic') && /REPORTTEXT-SENTINEL|RECORDTEXT-SENTINEL/.test(c.prompt)) probs.push(c.label + ' carries the worker texts')
    }
    const ids = (result.forPavol || []).map(i => i.id)
    console.log((probs.length ? 'BAD  ' : 'ok   ') + sc.name + ': ' + after + (ids.length ? '; items ' + ids.join(', ') : '') + (probs.length ? '\n     ' + probs.join('\n     ') : ''))
    bad += probs.length
    if (sc === SCEN[0]) {
      fs.mkdirSync(path.join(S, 'prompts'), { recursive: true })
      for (const c of calls) fs.writeFileSync(path.join(S, 'prompts', c.label.replace(/[:]/g, '_') + '.txt'), c.prompt)
    }
  }
  console.log('problems: ' + bad)
})().catch(e => { console.log('THREW', e && e.stack); process.exit(1) })

